import{_ as e,o as a,c as d,ag as i}from"./chunks/framework.DaCm-iTo.js";const m=JSON.parse('{"title":"EmakiAttribute","description":"","frontmatter":{},"headers":[],"relativePath":"en/modules/attribute/index.md","filePath":"en/modules/attribute/index.md","lastUpdated":null}'),o={name:"en/modules/attribute/index.md"};function r(s,t,n,l,c,h){return a(),d("div",null,[...t[0]||(t[0]=[i(`<h1 id="emakiattribute" tabindex="-1">EmakiAttribute <a class="header-anchor" href="#emakiattribute" aria-label="Permalink to &quot;EmakiAttribute&quot;">​</a></h1><p>EmakiAttribute owns real stats, resources, and combat calculation. It defines RPG attributes, damage types, and conditions, then exposes PDC attribute APIs for other modules. Equipment stats should be written as Attribute payloads, not only as lore text.</p><h2 id="basic-information" tabindex="-1">Basic information <a class="header-anchor" href="#basic-information" aria-label="Permalink to &quot;Basic information&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Item</th><th>Value</th></tr></thead><tbody><tr><td>Module version</td><td><code>4.6.9</code></td></tr><tr><td>Main command</td><td><code>/emakiattribute</code></td></tr><tr><td>Aliases</td><td><code>/eattribute</code>, <code>/ea</code></td></tr><tr><td>Hard dependency</td><td>EmakiCoreLib</td></tr><tr><td>Soft dependencies</td><td>MythicMobs, PlaceholderAPI, MMOItems</td></tr><tr><td>Default permissions</td><td><code>emakiattribute.use</code> and <code>emakiattribute.points</code> default to true; other administrative permissions default to op</td></tr></tbody></table><h2 id="what-it-solves" tabindex="-1">What it solves <a class="header-anchor" href="#what-it-solves" aria-label="Permalink to &quot;What it solves&quot;">​</a></h2><p>When vanilla attributes are not enough for RPG combat, use EmakiAttribute to define your own stat and damage logic, such as:</p><ul><li>physical, spell, and projectile attack.</li><li>physical, spell, and projectile defense.</li><li>critical chance, critical damage, and critical resistance.</li><li>armor penetration, spell penetration, and true damage.</li><li>health, mana, regeneration, dodge, lifesteal, attack speed, movement speed, and vanilla attribute mapping.</li></ul><p>Stats can come from PDC payloads written by Item, Forge, Strengthen, Gem, Skills, or external modules. Attribute aggregates and calculates them instead of forcing each plugin to implement its own stat system.</p><h2 id="default-runtime-folder" tabindex="-1">Default runtime folder <a class="header-anchor" href="#default-runtime-folder" aria-label="Permalink to &quot;Default runtime folder&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>plugins/EmakiAttribute/</span></span>
<span class="line"><span>├── config.yml</span></span>
<span class="line"><span>├── attribute_balance.yml</span></span>
<span class="line"><span>├── attributes/</span></span>
<span class="line"><span>├── conditions/</span></span>
<span class="line"><span>├── damage_types/</span></span>
<span class="line"><span>├── lore_formats/</span></span>
<span class="line"><span>├── presets/</span></span>
<span class="line"><span>├── gui/</span></span>
<span class="line"><span>├── lang/</span></span>
<span class="line"><span>└── data/</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Path</th><th>Purpose</th></tr></thead><tbody><tr><td><code>attributes/</code></td><td>Attribute definitions.</td></tr><tr><td><code>damage_types/</code></td><td>Damage types such as physical, projectile, and spell.</td></tr><tr><td><code>conditions/</code></td><td>Attribute read conditions (PDC read rules).</td></tr><tr><td><code>lore_formats/</code></td><td>How attributes are displayed in lore.</td></tr><tr><td><code>attribute_balance.yml</code></td><td>Attribute balance semantics and power score weights.</td></tr><tr><td><code>presets/</code></td><td>Attribute preset definitions.</td></tr><tr><td><code>gui/</code></td><td>Attribute points GUI configuration (<code>attribute_points.yml</code>).</td></tr><tr><td><code>lang/</code></td><td>Language files (bundled <code>zh_CN.yml</code> and <code>en_US.yml</code>).</td></tr><tr><td><code>data/</code></td><td>Runtime data, for example <code>data/parent_attributes/&lt;UUID&gt;.yml</code>.</td></tr></tbody></table><h2 id="typical-workflow" tabindex="-1">Typical workflow <a class="header-anchor" href="#typical-workflow" aria-label="Permalink to &quot;Typical workflow&quot;">​</a></h2><ol><li>Define attributes in <code>attributes/</code>.</li><li>Define display formats in <code>lore_formats/</code>.</li><li>Configure damage calculation in <code>damage_types/</code>.</li><li>Let Item / Forge / Strengthen / Gem write attribute payloads.</li><li>Attribute aggregates player stats after equipment changes or resync.</li><li>Combat uses damage type, attacker stats, and target stats to calculate the result.</li><li>Messages, action bars, PlaceholderAPI, or debug output can show the result.</li></ol><h2 id="relations-with-other-modules" tabindex="-1">Relations with other modules <a class="header-anchor" href="#relations-with-other-modules" aria-label="Permalink to &quot;Relations with other modules&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Module</th><th>Integration</th></tr></thead><tbody><tr><td>EmakiItem</td><td>Items can carry base attributes and set attributes.</td></tr><tr><td>EmakiForge</td><td>Forge results can write extra attributes.</td></tr><tr><td>EmakiStrengthen</td><td>Strengthen stars can add attributes.</td></tr><tr><td>EmakiGem</td><td>Gems can provide attributes.</td></tr><tr><td>EmakiSkills</td><td>Skills can read or consume Attribute resources and check stat requirements.</td></tr><tr><td>MythicMobs</td><td>Can participate in skill or mob combat ecosystems.</td></tr><tr><td>PlaceholderAPI</td><td>Exposes player stats, resources, or combat data.</td></tr></tbody></table><h2 id="pages" tabindex="-1">Pages <a class="header-anchor" href="#pages" aria-label="Permalink to &quot;Pages&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Page</th><th>Content</th></tr></thead><tbody><tr><td><a href="./configuration.html">Configuration</a></td><td>Main config, attribute folders, damage folders, condition folders, and troubleshooting order.</td></tr><tr><td><a href="./attributes.html">Attributes</a></td><td>Attribute fields, display formats, and ID design.</td></tr><tr><td><a href="./scaling-curves.html">Scaling Curves</a></td><td>Thresholds, curves, and balancing advice for high stat values.</td></tr><tr><td><a href="./damage.html">Damage</a></td><td>Multi-stage damage pipeline, hard lock, hit feedback, and recovery config.</td></tr><tr><td><a href="./conditions.html">Conditions</a></td><td>Equipment conditions, attribute conditions, and cross-module conditions.</td></tr><tr><td><a href="./lore-formats.html">Lore Formats</a></td><td>Lore display templates and read patterns.</td></tr><tr><td><a href="./commands.html">Commands</a></td><td><code>/ea</code> commands, lint, preview, dump, source, trace, and debug.</td></tr><tr><td><a href="./placeholders.html">Placeholders</a></td><td>PlaceholderAPI output and damage message template variables.</td></tr><tr><td><a href="./mythic.html">MythicMobs</a></td><td>Damage mechanic, temporary attribute mechanics, and attribute condition.</td></tr><tr><td><a href="./corelib-actions.html">CoreLib Actions</a></td><td>Action IDs and parameters registered by Attribute.</td></tr><tr><td><a href="./api.html">API</a></td><td><code>EmakiAttributeApi</code>, <code>PdcAttributeApi</code>, and integration contracts.</td></tr><tr><td><a href="./events.html">Events</a></td><td>Public Bukkit events.</td></tr><tr><td><a href="./damage-event.html">Damage Event</a></td><td><code>EmakiAttributeDamageEvent</code> in detail.</td></tr></tbody></table><h2 id="suggested-configuration-order" tabindex="-1">Suggested configuration order <a class="header-anchor" href="#suggested-configuration-order" aria-label="Permalink to &quot;Suggested configuration order&quot;">​</a></h2><ol><li>Start the server with default attributes and confirm the module loads.</li><li>Add or edit one attribute file, then run reload / lint.</li><li>Write that attribute onto one test item.</li><li>Use preview / dump commands to confirm the attribute is read.</li><li>Then configure damage types and combat tests.</li></ol><h2 id="main-config-yml-fields" tabindex="-1">Main config.yml fields <a class="header-anchor" href="#main-config-yml-fields" aria-label="Permalink to &quot;Main config.yml fields&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>language</code></td><td>string</td><td><code>zh_CN</code></td><td>Language file name under <code>lang/</code>.</td></tr><tr><td><code>release_default_data</code></td><td>boolean</td><td><code>true</code></td><td>Whether bundled sample attributes, damage types, conditions, and lore formats are released.</td></tr><tr><td><code>hard_lock_damage</code></td><td>boolean</td><td><code>true</code></td><td>Global damage hard lock. When true, all matching damage events go through the attribute system.</td></tr><tr><td><code>default_damage_type</code></td><td>string</td><td><code>physical</code></td><td>Fallback damage type id.</td></tr><tr><td><code>projectile_damage_type</code></td><td>string</td><td><code>projectile</code></td><td>Damage type used when projectiles hit.</td></tr><tr><td><code>vanilla_event_damage.enabled</code></td><td>boolean</td><td><code>true</code></td><td>Perfect takeover of vanilla event damage; disabling it uses compatibility synthetic damage mode.</td></tr><tr><td><code>vanilla_event_damage.damage_type</code></td><td>string</td><td>same as <code>default_damage_type</code></td><td>Damage type used for unmapped vanilla damage.</td></tr><tr><td><code>same_signature_ignores_invulnerability.enabled</code></td><td>boolean</td><td><code>true</code></td><td>Whether same-batch, same-signature hits bypass the vanilla invulnerability window.</td></tr><tr><td><code>same_signature_ignores_invulnerability.window_ms</code></td><td>long</td><td><code>500</code></td><td>Batch window in milliseconds.</td></tr><tr><td><code>regen_interval_ticks</code></td><td>integer</td><td><code>20</code></td><td>Resource regeneration interval in ticks. Minimum 1; 20 ticks = 1 second.</td></tr><tr><td><code>sync_delay_ticks</code></td><td>integer</td><td><code>1</code></td><td>Ticks to wait after an equipment change before syncing. Minimum 0.</td></tr><tr><td><code>health_display_scaling.enabled</code></td><td>boolean</td><td><code>false</code></td><td>Whether the client health bar is compressed; real health and damage are unaffected.</td></tr><tr><td><code>health_display_scaling.target</code></td><td>double</td><td><code>20.0</code></td><td>Target displayed health on the client.</td></tr><tr><td><code>synthetic_hit_feedback.knockback</code></td><td>boolean</td><td><code>true</code></td><td>Whether compatibility-mode synthetic damage re-applies knockback.</td></tr><tr><td><code>synthetic_hit_feedback.knockback_strength</code></td><td>double</td><td><code>0.4</code></td><td>Knockback strength.</td></tr><tr><td><code>synthetic_hit_feedback.hurt_sound</code></td><td>boolean</td><td><code>true</code></td><td>Whether compatibility-mode synthetic damage plays a hurt sound.</td></tr></tbody></table><h3 id="resource-configuration" tabindex="-1">Resource configuration <a class="header-anchor" href="#resource-configuration" aria-label="Permalink to &quot;Resource configuration&quot;">​</a></h3><p><code>default_profile.resources</code> defines the player&#39;s default resources:</p><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>id</code></td><td>string</td><td>section key</td><td>Resource id such as <code>health</code> or <code>mana</code>; bundled config uses the section key.</td></tr><tr><td><code>display_name</code></td><td>string</td><td>same as <code>id</code></td><td>Display name.</td></tr><tr><td><code>default_max</code></td><td>double</td><td><code>0</code></td><td>Default maximum.</td></tr><tr><td><code>min_max</code></td><td>double</td><td><code>0</code></td><td>Lower bound of the maximum after bonuses.</td></tr><tr><td><code>max_max</code></td><td>double</td><td>very large</td><td>Upper bound of the maximum.</td></tr><tr><td><code>sync_to_bukkit</code></td><td>boolean</td><td><code>false</code></td><td>Whether to sync to vanilla Bukkit health (only needed for the health resource).</td></tr><tr><td><code>full_on_init</code></td><td>boolean</td><td><code>true</code></td><td>Whether the resource is filled on initialization.</td></tr><tr><td><code>regen_per_second</code></td><td>double</td><td><code>0</code></td><td>Natural regeneration per second.</td></tr></tbody></table><p>Bundled default resources:</p><ul><li><code>health</code>: default max 20, synced to Bukkit, min max 1, max max 2048.</li><li><code>mana</code>: default max 100, not synced to Bukkit, min max 0, max max 99999.</li></ul><h2 id="attribute-actions" tabindex="-1">Attribute actions <a class="header-anchor" href="#attribute-actions" aria-label="Permalink to &quot;Attribute actions&quot;">​</a></h2><p>EmakiAttribute registers attribute damage, temporary attribute, resource, tag, and synchronization actions into CoreLib. Full action IDs, parameters, and examples are documented in <a href="./corelib-actions.html">CoreLib Actions</a>.</p><p>Common examples:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">actions</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;attributedamage amount=50 type=physical&#39;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;attribute_add effect_id=forge_buff attribute=physical_attack value=20 duration_ticks=10s&#39;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;attribute_resource_consume resource=mana amount=20&#39;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;attribute_sync all=false&#39;</span></span></code></pre></div>`,30)])])}const p=e(o,[["render",r]]);export{m as __pageData,p as default};
